/// Idiomas de la app: los oficiales de España, inglés, alemán, italiano, holandés y francés.
const idiomas = <String, String>{
  'es': 'Castellano',
  'ca': 'Català',
  'gl': 'Galego',
  'eu': 'Euskara',
  'en': 'English',
  'de': 'Deutsch',
  'it': 'Italiano',
  'nl': 'Nederlands',
  'fr': 'Français',
};

/// Idioma en uso (lo fija IdiomaNotifier). Lo usan tr() y los formatos de fecha.
String idiomaActual = 'es';

const _orden = ['ca', 'gl', 'eu', 'en', 'de', 'it', 'nl', 'fr'];

/// Traduce un texto escrito en castellano. Si aún no tiene traducción, se queda en castellano.
String tr(String es) {
  if (idiomaActual == 'es') return es;
  final i = _orden.indexOf(idiomaActual);
  final t = _textos[es];
  return (i < 0 || t == null) ? es : t[i];
}

/// Traduce una plantilla con huecos {nombre}: trf('Debes {x}', {'x': '12 €'}).
String trf(String plantilla, Map<String, Object> valores) {
  var t = tr(plantilla);
  valores.forEach((k, v) => t = t.replaceAll('{$k}', '$v'));
  return t;
}

/// Text traducido. Se puede usar como `const Tx('Guardar')` y se redibuja al cambiar de idioma.
class Tx extends StatelessWidget {
  const Tx(this.texto, {super.key, this.style, this.textAlign, this.overflow, this.maxLines, this.softWrap});
  final String texto;
  final TextStyle? style;
  final TextAlign? textAlign;
  final TextOverflow? overflow;
  final int? maxLines;
  final bool? softWrap;

  @override
  Widget build(BuildContext context) {
    Localizations.maybeLocaleOf(context); // dependencia: se reconstruye al cambiar el idioma
    return Text(tr(texto), style: style, textAlign: textAlign, overflow: overflow, maxLines: maxLines, softWrap: softWrap);
  }
}

const _clave = 'idioma_app';

class IdiomaNotifier extends Notifier<String> {
  @override
  String build() {
    var c = ref.watch(prefsProvider).getString(_clave);
    // 0060: castellano por defecto; cada uno lo cambia en el selector
    if (c == null || !idiomas.containsKey(c)) c = 'es';
    idiomaActual = c;
    return c;
  }

  Future<void> elegir(String codigo) async {
    idiomaActual = codigo;
    state = codigo;
    await ref.read(prefsProvider).setString(_clave, codigo);
    await sincronizarIdioma();
  }
}

/// Guarda el idioma en el perfil para que los avisos (push y campana) lleguen en ese idioma.
Future<void> sincronizarIdioma() async {
  final uid = sb.auth.currentUser?.id;
  if (uid == null) return;
  try {
    await sb.from('perfiles').update({'idioma': idiomaActual}).eq('id', uid);
  } catch (_) {}
}

final idiomaProvider = NotifierProvider<IdiomaNotifier, String>(IdiomaNotifier.new);

/// Bandera emoji de cada idioma. Catalán, gallego y euskera no tienen emoji: se dibujan (BanderaIdioma).
const banderasIdioma = <String, String>{
  'es': '🇪🇸', 'en': '🇬🇧', 'de': '🇩🇪', 'it': '🇮🇹', 'nl': '🇳🇱', 'fr': '🇫🇷',
};

/// Bandera de un idioma: emoji o, para ca/gl/eu, la senyera, la bandera de Galicia y la ikurriña dibujadas.
class BanderaIdioma extends StatelessWidget {
  const BanderaIdioma(this.idioma, {super.key, this.alto = 16});
  final String idioma;
  final double alto;

  @override
  Widget build(BuildContext context) {
    final emoji = banderasIdioma[idioma];
    if (emoji != null) return Text(emoji, style: TextStyle(fontSize: alto * 1.1, height: 1));
    if (!const {'ca', 'gl', 'eu'}.contains(idioma)) {
      return Text(idioma.toUpperCase(), style: TextStyle(fontSize: alto * 0.75, fontWeight: FontWeight.w700));
    }
    return ClipRRect(
      borderRadius: BorderRadius.circular(2),
      child: SizedBox(
        width: alto * 1.5,
        height: alto,
        child: CustomPaint(painter: _PintorBandera(idioma)),
      ),
    );
  }
}

class _PintorBandera extends CustomPainter {
  _PintorBandera(this.idioma);
  final String idioma;

  @override
  void paint(Canvas c, Size s) {
    final r = Offset.zero & s;
    final p = Paint()..isAntiAlias = true;
    switch (idioma) {
      case 'ca': // Senyera: 9 franjas, amarillo y rojo
        p.color = const Color(0xFFFCDD09);
        c.drawRect(r, p);
        p.color = const Color(0xFFDA121A);
        final f = s.height / 9;
        for (var i = 1; i < 9; i += 2) {
          c.drawRect(Rect.fromLTWH(0, f * i, s.width, f), p);
        }
      case 'gl': // Galicia: blanco con banda azul en diagonal
        p.color = Colors.white;
        c.drawRect(r, p);
        p
          ..color = const Color(0xFF0099CC)
          ..strokeWidth = s.height * 0.24
          ..strokeCap = StrokeCap.square;
        c.drawLine(Offset.zero, Offset(s.width, s.height), p);
        p
          ..style = PaintingStyle.stroke
          ..strokeWidth = 0.6
          ..color = const Color(0x33000000);
        c.drawRect(r.deflate(0.3), p);
      case 'eu': // Ikurriña: rojo, aspa verde y cruz blanca
        p.color = const Color(0xFFD52B1E);
        c.drawRect(r, p);
        p
          ..color = const Color(0xFF009B48)
          ..strokeWidth = s.height * 0.16;
        c.drawLine(Offset.zero, Offset(s.width, s.height), p);
        c.drawLine(Offset(s.width, 0), Offset(0, s.height), p);
        p.color = Colors.white;
        final g = s.height * 0.14;
        c.drawRect(Rect.fromLTWH(0, (s.height - g) / 2, s.width, g), p);
        c.drawRect(Rect.fromLTWH((s.width - g) / 2, 0, g, s.height), p);
    }
  }

  @override
  bool shouldRepaint(_PintorBandera old) => old.idioma != idioma;
}

/// Selector de idioma compacto (0060): la bandera y el idioma actual; al tocar, la lista completa.
class SelectorIdioma extends ConsumerWidget {
  const SelectorIdioma({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final actual = ref.watch(idiomaProvider);
    final cs = Theme.of(context).colorScheme;
    return PopupMenuButton<String>(
      tooltip: 'Idioma',
      initialValue: actual,
      onSelected: (c) => ref.read(idiomaProvider.notifier).elegir(c),
      itemBuilder: (_) => [
        for (final e in idiomas.entries)
          PopupMenuItem(
            value: e.key,
            child: Row(children: [
              SizedBox(width: 28, child: Center(child: BanderaIdioma(e.key, alto: 16))),
              const SizedBox(width: 10),
              Expanded(child: Text(e.value)),
              if (e.key == actual) Icon(Icons.check, size: 18, color: cs.primary),
            ]),
          ),
      ],
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(20),
          border: Border.all(color: cs.outlineVariant),
        ),
        child: Row(mainAxisSize: MainAxisSize.min, children: [
          BanderaIdioma(actual, alto: 14),
          const SizedBox(width: 8),
          Text(idiomas[actual] ?? actual, style: Theme.of(context).textTheme.labelLarge),
          const Icon(Icons.arrow_drop_down, size: 20),
        ]),
      ),
    );
  }
}

